{
  "id": "22222222-2222-2222-2222-222222222222",
  "name": "DS-T2 crear_pedido_contraentrega",
  "active": true,
  "nodes": [
    {
      "parameters": {},
      "id": "trigger",
      "name": "Execute Workflow Trigger",
      "type": "n8n-nodes-base.executeWorkflowTrigger",
      "typeVersion": 1,
      "position": [
        0,
        0
      ]
    },
    {
      "parameters": {
        "method": "POST",
        "url": "={{ ($env.SHOPIFY_STORE_DOMAIN.includes('host.docker') ? 'http://' : 'https://') + $env.SHOPIFY_STORE_DOMAIN + '/admin/api/' + $env.SHOPIFY_API_VERSION + '/graphql.json' }}",
        "sendHeaders": true,
        "headerParameters": {
          "parameters": [
            {
              "name": "X-Shopify-Access-Token",
              "value": "={{ $env.SHOPIFY_API_KEY }}"
            }
          ]
        },
        "sendBody": true,
        "specifyBody": "json",
        "jsonBody": "={{ JSON.stringify({ query: 'mutation orderCreate($order: OrderCreateOrderInput!) { orderCreate(order: $order) { order { id name } userErrors { field message } } }', variables: { order: { email: $json.email, phone: $json.telefono, lineItems: [{ variantId: $json.variant_id, quantity: $json.cantidad }], shippingAddress: { address1: $json.direccion, city: $json.ciudad, province: $json.departamento, countryCode: 'CO', firstName: $json.nombre, lastName: $json.apellido }, financialStatus: 'PENDING', tags: ['wa:' + $json.wa_id, 'contraentrega'] } } }) }}"
      },
      "id": "Node1",
      "name": "Shopify API",
      "type": "n8n-nodes-base.httpRequest",
      "typeVersion": 4.2,
      "position": [
        200,
        0
      ]
    },
    {
      "parameters": {
        "jsCode": "\nconst res = $input.first().json;\nif (res.data && res.data.orderCreate && res.data.orderCreate.order) {\n  return [{ json: { exito: true, order_id: res.data.orderCreate.order.id, order_name: res.data.orderCreate.order.name } }];\n}\nreturn [{ json: { exito: false, error: res.data?.orderCreate?.userErrors || 'Error desconocido' } }];\n      "
      },
      "id": "Node2",
      "name": "Response",
      "type": "n8n-nodes-base.code",
      "typeVersion": 2,
      "position": [
        400,
        0
      ]
    }
  ],
  "connections": {
    "Execute Workflow Trigger": {
      "main": [
        [
          {
            "node": "Shopify API",
            "type": "main",
            "index": 0
          }
        ]
      ]
    },
    "Shopify API": {
      "main": [
        [
          {
            "node": "Response",
            "type": "main",
            "index": 0
          }
        ]
      ]
    }
  },
  "settings": {
    "executionOrder": "v1",
    "saveDataSuccessExecution": "none",
    "saveDataErrorExecution": "all"
  }
}

